PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?decision ?decisionLabel ?rel ?target ?targetLabel ?targetType WHERE {
  VALUES ?decision { <https://moosedev.dev/kg/ArchitecturalDecision/ac328b9e-f9cf-4e42-aa27-6e1847134e12> }
  OPTIONAL { ?decision rdfs:label ?decisionLabel }
  { ?decision <https://moosedev.dev/kg/isMotivatedBy> ?target . BIND("isMotivatedBy" AS ?rel) }
  UNION
  { ?decision <https://moosedev.dev/kg/isConstrainedBy> ?target . BIND("isConstrainedBy" AS ?rel) }
  OPTIONAL { ?target rdfs:label ?targetLabel }
  OPTIONAL { ?target a ?targetType }
}
ORDER BY ?rel ?targetLabel

